-- STATIC SELECT ONLY. FAILS CLOSED until Human-reviewed Preflight pins are bound.
-- PG17/18: NOT NULL is checked through each column's pg_attribute.attnotnull.
-- Only redundant validated/enforced pg_constraint NOT NULL entries are omitted.
WITH state AS MATERIALIZED (WITH funcs AS (
 SELECT p.proname||'('||pg_get_function_identity_arguments(p.oid)||')' signature,jsonb_build_object(
 'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,
 'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END COLLATE "C",x.privilege_type COLLATE "C"),'[]') FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x)) evidence
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN('visual_assets_admin','visual_assets_write')
), relations AS (
 SELECT c.relname,jsonb_build_object('owner',pg_get_userbyid(c.relowner),'kind',c.relkind,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,
 'acl',(SELECT coalesce(jsonb_agg(jsonb_build_array(CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END,x.privilege_type,x.is_grantable) ORDER BY CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x.grantee) END COLLATE "C",x.privilege_type COLLATE "C"),'[]') FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) x),
 'columns',(SELECT jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_array(conname,pg_get_constraintdef(oid)) ORDER BY conname COLLATE "C") FROM pg_constraint WHERE conrelid=c.oid AND (contype<>'n' OR NOT convalidated OR coalesce((to_jsonb(pg_constraint)->>'conenforced')::boolean,true) IS NOT TRUE)),
 'indexes',(SELECT jsonb_agg(indexdef ORDER BY indexname COLLATE "C") FROM pg_indexes WHERE schemaname='public' AND tablename=c.relname),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY policyname COLLATE "C") FROM pg_policies p WHERE schemaname='public' AND tablename=c.relname),
 'triggers',(SELECT coalesce(jsonb_agg(pg_get_triggerdef(t.oid) ORDER BY t.tgname COLLATE "C"),'[]') FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) evidence
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN('visual_assets','visual_asset_mappings')
), policies AS (SELECT to_jsonb(p) evidence,policyname FROM pg_policies p WHERE schemaname='storage' AND tablename='objects' AND policyname LIKE 'visual083_%'),
 existing AS (SELECT jsonb_build_object(
 'profiles', (SELECT coalesce(jsonb_agg(jsonb_build_array(id,encode(sha256(convert_to((to_jsonb(u))::text,'UTF8')),'hex')) ORDER BY id),'[]') FROM public.user_profiles u),
 'buckets',(SELECT coalesce(jsonb_agg(to_jsonb(b) ORDER BY id COLLATE "C"),'[]') FROM storage.buckets b WHERE id<>'vp-visual-assets'),
 'objects',(SELECT coalesce(jsonb_agg(jsonb_build_array(id,encode(sha256(convert_to((to_jsonb(o))::text,'UTF8')),'hex')) ORDER BY id),'[]') FROM storage.objects o WHERE bucket_id<>'vp-visual-assets')) rows,
 jsonb_build_object('storage_policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY policyname COLLATE "C"),'[]') FROM pg_policies p WHERE schemaname='storage' AND tablename='objects' AND policyname NOT LIKE 'visual083_%'),
 'storage_security',(SELECT jsonb_build_array(relrowsecurity,relforcerowsecurity,pg_get_userbyid(relowner),relacl::text) FROM pg_class WHERE oid='storage.objects'::regclass),
 'admin_helper',(SELECT jsonb_build_array(pg_get_functiondef(p.oid),pg_get_userbyid(p.proowner),p.proacl::text) FROM pg_proc p WHERE p.oid=to_regprocedure('public.people_is_active_admin()'))) security)
 SELECT jsonb_build_object('contract',jsonb_build_object(
 'functions',(SELECT coalesce(jsonb_object_agg(signature,evidence),'{}') FROM funcs),
 'tables',(SELECT coalesce(jsonb_object_agg(relname,evidence),'{}') FROM relations),
 'policies',(SELECT coalesce(jsonb_agg(evidence ORDER BY policyname COLLATE "C"),'[]') FROM policies),
 'bucket',(SELECT jsonb_build_object('id',id,'name',name,'public',public,'file_size_limit',file_size_limit,'allowed_mime_types',allowed_mime_types) FROM storage.buckets WHERE id='vp-visual-assets')),
 'rows',rows,'security',security) FROM existing),expected AS(SELECT '{"bucket":{"id":"vp-visual-assets","name":"vp-visual-assets","public":false,"file_size_limit":20971520,"allowed_mime_types":["image/jpeg","image/png","image/webp"]},"tables":{"visual_assets":{"acl":[["authenticated","SELECT",false],["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false]],"rls":true,"kind":"r","owner":"postgres","forced":false,"columns":[["id","uuid",true,null],["artwork_key","text",true,null],["name_th","text",true,null],["name_en","text",true,null],["asset_type","text",true,null],["scope","text",true,null],["theme","text",true,"''''::text"],["tags","text[]",true,"''{}''::text[]"],["status","text",true,"''draft''::text"],["master_path","text",true,null],["thumbnail_path","text",true,null],["width","integer",true,null],["height","integer",true,null],["byte_size","integer",true,null],["thumbnail_bytes","integer",true,null],["sha256","text",true,null],["overlay_ready","boolean",true,null],["delete_pending","boolean",true,"false"],["version","integer",true,"1"],["created_by","uuid",true,null],["updated_by","uuid",true,null],["created_at","timestamp with time zone",true,"now()"],["updated_at","timestamp with time zone",true,"now()"]],"indexes":["CREATE UNIQUE INDEX visual_assets_artwork_key_key ON public.visual_assets USING btree (artwork_key)","CREATE UNIQUE INDEX visual_assets_master_path_key ON public.visual_assets USING btree (master_path)","CREATE UNIQUE INDEX visual_assets_pkey ON public.visual_assets USING btree (id)","CREATE UNIQUE INDEX visual_assets_thumbnail_path_key ON public.visual_assets USING btree (thumbnail_path)"],"policies":[{"cmd":"SELECT","qual":"visual_assets_admin()","roles":["authenticated"],"tablename":"visual_assets","permissive":"PERMISSIVE","policyname":"visual083_assets_read","schemaname":"public","with_check":null}],"triggers":[],"constraints":[["visual_assets_artwork_key_check","CHECK ((artwork_key ~ ''^[a-z][a-z0-9_-]{2,79}$''::text))"],["visual_assets_artwork_key_key","UNIQUE (artwork_key)"],["visual_assets_asset_type_check","CHECK ((asset_type = ANY (ARRAY[''journey''::text, ''background''::text, ''banner''::text, ''illustration''::text])))"],["visual_assets_byte_size_check","CHECK (((byte_size >= 1) AND (byte_size <= 20971520)))"],["visual_assets_check","CHECK (((NOT delete_pending) OR (status = ''retired''::text)))"],["visual_assets_created_by_fkey","FOREIGN KEY (created_by) REFERENCES user_profiles(id) ON DELETE RESTRICT"],["visual_assets_height_check","CHECK (((height >= 1) AND (height <= 2560)))"],["visual_assets_master_path_check","CHECK ((master_path ~ ''^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/master\\.webp$''::text))"],["visual_assets_master_path_key","UNIQUE (master_path)"],["visual_assets_name_en_check","CHECK (((length(btrim(name_en)) >= 1) AND (length(btrim(name_en)) <= 160)))"],["visual_assets_name_th_check","CHECK (((length(btrim(name_th)) >= 1) AND (length(btrim(name_th)) <= 160)))"],["visual_assets_overlay_ready_check","CHECK (overlay_ready)"],["visual_assets_pkey","PRIMARY KEY (id)"],["visual_assets_scope_check","CHECK ((scope = ANY (ARRAY[''non_litigation''::text, ''case''::text, ''both''::text])))"],["visual_assets_sha256_check","CHECK ((sha256 ~ ''^[0-9a-f]{64}$''::text))"],["visual_assets_status_check","CHECK ((status = ANY (ARRAY[''draft''::text, ''active''::text, ''retired''::text])))"],["visual_assets_tags_check","CHECK (((cardinality(tags) <= 12) AND (length((tags)::text) <= 600)))"],["visual_assets_theme_check","CHECK ((length(theme) <= 80))"],["visual_assets_thumbnail_bytes_check","CHECK (((thumbnail_bytes >= 1) AND (thumbnail_bytes <= 2097152)))"],["visual_assets_thumbnail_path_check","CHECK ((thumbnail_path ~ ''^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/thumbnail\\.webp$''::text))"],["visual_assets_thumbnail_path_key","UNIQUE (thumbnail_path)"],["visual_assets_updated_by_fkey","FOREIGN KEY (updated_by) REFERENCES user_profiles(id) ON DELETE RESTRICT"],["visual_assets_width_check","CHECK (((width >= 1) AND (width <= 2560)))"]]},"visual_asset_mappings":{"acl":[["authenticated","SELECT",false],["postgres","DELETE",false],["postgres","INSERT",false],["postgres","MAINTAIN",false],["postgres","REFERENCES",false],["postgres","SELECT",false],["postgres","TRIGGER",false],["postgres","TRUNCATE",false],["postgres","UPDATE",false]],"rls":true,"kind":"r","owner":"postgres","forced":false,"columns":[["scope","text",true,null],["family_key","text",true,null],["artwork_key","text",true,null],["updated_by","uuid",true,null],["updated_at","timestamp with time zone",true,"now()"]],"indexes":["CREATE UNIQUE INDEX visual_asset_mappings_pkey ON public.visual_asset_mappings USING btree (scope, family_key)"],"policies":[{"cmd":"SELECT","qual":"visual_assets_admin()","roles":["authenticated"],"tablename":"visual_asset_mappings","permissive":"PERMISSIVE","policyname":"visual083_mappings_read","schemaname":"public","with_check":null}],"triggers":[],"constraints":[["visual_asset_mappings_artwork_key_fkey","FOREIGN KEY (artwork_key) REFERENCES visual_assets(artwork_key) ON UPDATE RESTRICT ON DELETE RESTRICT"],["visual_asset_mappings_check","CHECK (((family_key <> ''universal''::text) OR (scope = ''both''::text)))"],["visual_asset_mappings_family_key_check","CHECK ((family_key ~ ''^[a-z][a-z0-9_-]{2,79}$''::text))"],["visual_asset_mappings_pkey","PRIMARY KEY (scope, family_key)"],["visual_asset_mappings_scope_check","CHECK ((scope = ANY (ARRAY[''non_litigation''::text, ''case''::text, ''both''::text])))"],["visual_asset_mappings_updated_by_fkey","FOREIGN KEY (updated_by) REFERENCES user_profiles(id) ON DELETE RESTRICT"]]}},"policies":[{"cmd":"DELETE","qual":"(bucket_id <> ''vp-visual-assets''::text)","roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"visual083_delete_ceiling","schemaname":"storage","with_check":null},{"cmd":"INSERT","qual":null,"roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"visual083_insert_ceiling","schemaname":"storage","with_check":"(bucket_id <> ''vp-visual-assets''::text)"},{"cmd":"SELECT","qual":"((bucket_id = ''vp-visual-assets''::text) AND visual_assets_admin())","roles":["authenticated"],"tablename":"objects","permissive":"PERMISSIVE","policyname":"visual083_read","schemaname":"storage","with_check":null},{"cmd":"SELECT","qual":"((bucket_id <> ''vp-visual-assets''::text) OR ((auth.role() = ''authenticated''::text) AND visual_assets_admin()))","roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"visual083_read_ceiling","schemaname":"storage","with_check":null},{"cmd":"UPDATE","qual":"(bucket_id <> ''vp-visual-assets''::text)","roles":["public"],"tablename":"objects","permissive":"RESTRICTIVE","policyname":"visual083_update_ceiling","schemaname":"storage","with_check":"(bucket_id <> ''vp-visual-assets''::text)"}],"functions":{"visual_assets_admin()":{"acl":[["anon","EXECUTE",false],["authenticated","EXECUTE",false],["postgres","EXECUTE",false]],"owner":"postgres","config":["search_path=public"],"definition":"CREATE OR REPLACE FUNCTION public.visual_assets_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\n SELECT public.people_is_active_admin() AND EXISTS(SELECT 1 FROM public.user_profiles WHERE id=auth.uid() AND must_change_password IS FALSE);\n$function$\n","volatility":"s","security_definer":true},"visual_assets_write(p_action text, p_id uuid, p_version integer, p_data jsonb)":{"acl":[["authenticated","EXECUTE",false],["postgres","EXECUTE",false]],"owner":"postgres","config":["search_path=public"],"definition":"CREATE OR REPLACE FUNCTION public.visual_assets_write(p_action text, p_id uuid, p_version integer, p_data jsonb DEFAULT ''{}''::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''public''\nAS $function$\nDECLARE a public.visual_assets%rowtype; actor uuid:=auth.uid(); old_key text;\nBEGIN\n IF NOT public.visual_assets_admin() THEN RAISE EXCEPTION ''VISUAL_FORBIDDEN'' USING ERRCODE=''42501''; END IF;\n IF jsonb_typeof(p_data)<>''object'' THEN RAISE EXCEPTION ''VISUAL_INVALID''; END IF;\n PERFORM pg_advisory_xact_lock(830083);\n IF p_action=''create'' THEN\n  IF (SELECT count(*) FROM public.visual_assets)>=50 THEN RAISE EXCEPTION ''VISUAL_LIMIT''; END IF;\n  IF split_part(p_data->>''master_path'',''/'',1)<>actor::text OR split_part(p_data->>''master_path'',''/'',2)<>p_id::text\n   OR replace(p_data->>''master_path'',''master.webp'',''thumbnail.webp'') IS DISTINCT FROM p_data->>''thumbnail_path''\n   OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=''vp-visual-assets'' AND name=p_data->>''master_path'')\n   OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=''vp-visual-assets'' AND name=p_data->>''thumbnail_path'')\n  THEN RAISE EXCEPTION ''VISUAL_FILE_REQUIRED''; END IF;\n  INSERT INTO public.visual_assets(id,artwork_key,name_th,name_en,asset_type,scope,theme,tags,status,master_path,thumbnail_path,width,height,byte_size,thumbnail_bytes,sha256,overlay_ready,created_by,updated_by)\n  VALUES(p_id,p_data->>''artwork_key'',p_data->>''name_th'',p_data->>''name_en'',p_data->>''asset_type'',p_data->>''scope'',coalesce(p_data->>''theme'',''''),\n   ARRAY(SELECT jsonb_array_elements_text(coalesce(p_data->''tags'',''[]''))),coalesce(p_data->>''status'',''draft''),p_data->>''master_path'',p_data->>''thumbnail_path'',\n   (p_data->>''width'')::integer,(p_data->>''height'')::integer,(p_data->>''byte_size'')::integer,(p_data->>''thumbnail_bytes'')::integer,p_data->>''sha256'',(p_data->>''overlay_ready'')::boolean,actor,actor) RETURNING * INTO a;\n ELSIF p_action IN (''map'',''unmap'') THEN\n  SELECT artwork_key INTO old_key FROM public.visual_asset_mappings WHERE scope=p_data->>''scope'' AND family_key=p_data->>''family_key'';\n  IF old_key IS DISTINCT FROM p_data->>''expected_key'' THEN RAISE EXCEPTION ''VISUAL_CONFLICT''; END IF;\n  IF p_action=''unmap'' THEN\n   DELETE FROM public.visual_asset_mappings WHERE scope=p_data->>''scope'' AND family_key=p_data->>''family_key'';\n  ELSE\n   SELECT * INTO a FROM public.visual_assets WHERE artwork_key=p_data->>''artwork_key'';\n   IF NOT FOUND OR a.status<>''active'' OR a.delete_pending OR NOT(a.scope=''both'' OR a.scope=p_data->>''scope'') THEN RAISE EXCEPTION ''VISUAL_MAPPING_INVALID''; END IF;\n   INSERT INTO public.visual_asset_mappings(scope,family_key,artwork_key,updated_by) VALUES(p_data->>''scope'',p_data->>''family_key'',a.artwork_key,actor)\n   ON CONFLICT(scope,family_key) DO UPDATE SET artwork_key=excluded.artwork_key,updated_by=actor,updated_at=now();\n  END IF;\n  RETURN jsonb_build_object(''saved'',true);\n ELSE\n  SELECT * INTO a FROM public.visual_assets WHERE id=p_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION ''VISUAL_NOT_FOUND''; END IF;\n  IF a.version IS DISTINCT FROM p_version THEN RAISE EXCEPTION ''VISUAL_CONFLICT''; END IF;\n  IF p_action=''edit'' AND NOT a.delete_pending THEN\n   IF EXISTS(SELECT 1 FROM public.visual_asset_mappings WHERE artwork_key=a.artwork_key)\n    AND (p_data->>''status'' IS DISTINCT FROM ''active'' OR p_data->>''scope'' IS DISTINCT FROM a.scope) THEN RAISE EXCEPTION ''VISUAL_IN_USE''; END IF;\n   UPDATE public.visual_assets SET name_th=p_data->>''name_th'',name_en=p_data->>''name_en'',asset_type=p_data->>''asset_type'',scope=p_data->>''scope'',\n    theme=coalesce(p_data->>''theme'',''''),tags=ARRAY(SELECT jsonb_array_elements_text(coalesce(p_data->''tags'',''[]''))),status=p_data->>''status'',\n    version=version+1,updated_at=now(),updated_by=actor WHERE id=a.id RETURNING * INTO a;\n  ELSIF p_action=''delete_begin'' THEN\n   IF EXISTS(SELECT 1 FROM public.visual_asset_mappings WHERE artwork_key=a.artwork_key) THEN RAISE EXCEPTION ''VISUAL_IN_USE''; END IF;\n   IF NOT a.delete_pending THEN\n    UPDATE public.visual_assets SET delete_pending=true,status=''retired'',version=version+1,updated_at=now(),updated_by=actor WHERE id=a.id RETURNING * INTO a;\n   END IF;\n  ELSIF p_action=''delete_finish'' AND a.delete_pending THEN\n   IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=''vp-visual-assets'' AND name IN(a.master_path,a.thumbnail_path)) THEN RAISE EXCEPTION ''VISUAL_CLEANUP_REQUIRED''; END IF;\n   DELETE FROM public.visual_assets WHERE id=a.id;\n   RETURN jsonb_build_object(''deleted'',true);\n  ELSE RAISE EXCEPTION ''VISUAL_INVALID''; END IF;\n END IF;\n RETURN to_jsonb(a);\nEND $function$\n","volatility":"v","security_definer":true}}}'::jsonb value),
 checks AS(SELECT jsonb_build_object('owner',current_user='postgres','reviewed_baseline_bound','08c5851fe53d31499cf53ccf64ded26cf33b4f945b5dee3e04da9f0ef09488b1' IS NOT NULL AND '27b35945b133182630a341593b8ebdbb2d4fda04cd616a02b5f808280a8faea1' IS NOT NULL,
 'applied_state_exact',state->'contract'=expected.value,'existing_rows_preserved',encode(sha256(convert_to((state->'rows')::text,'UTF8')),'hex') IS NOT DISTINCT FROM '08c5851fe53d31499cf53ccf64ded26cf33b4f945b5dee3e04da9f0ef09488b1',
 'existing_security_preserved',encode(sha256(convert_to((state->'security')::text,'UTF8')),'hex') IS NOT DISTINCT FROM '27b35945b133182630a341593b8ebdbb2d4fda04cd616a02b5f808280a8faea1',
 'no_artwork_seed',NOT EXISTS(SELECT 1 FROM public.visual_assets) AND NOT EXISTS(SELECT 1 FROM public.visual_asset_mappings) AND NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='vp-visual-assets')) value FROM state s(state),expected),
 failures AS(SELECT coalesce(jsonb_agg(key ORDER BY key COLLATE "C"),'[]') value FROM checks,jsonb_each(checks.value) c(key,passed) WHERE passed IS DISTINCT FROM 'true'::jsonb)
SELECT jsonb_build_object('gate_pass',failures.value='[]'::jsonb,'failed_checks',failures.value,'checks',checks.value,'candidate_sha256','3682c449f708f600468f6cbd36d3b6de60fd7cc5850f6e9802f38b898481edfa',
 'rows_sha256',encode(sha256(convert_to((state->'rows')::text,'UTF8')),'hex'),'security_sha256',encode(sha256(convert_to((state->'security')::text,'UTF8')),'hex'),'business_rpc_executed',false,
 'object_differences',(SELECT coalesce(jsonb_agg(k ORDER BY k COLLATE "C"),'[]') FROM jsonb_object_keys(expected.value|| (state->'contract')) k WHERE expected.value->k IS DISTINCT FROM state->'contract'->k))
 FROM state s(state),expected,checks,failures;
